function trouble({ os, title, slug, path, steps, keywords, aliases, source_url, caution, impact, difficulty = "beginner", estimate_minutes = 5 }) {
  return {
    title, slug, os, version: VERSION[os], category: "troubleshoot",
    aliases: aliases?.length ? aliases : [title], path, steps, related_slugs: [],
    keywords: keywords?.length ? keywords : [title],
    description: `${title}の確認手順です。`, source_url,
    verified_at: VERIFIED_AT, review_due_at: REVIEW_DUE_AT,
    difficulty, estimate_minutes,
    device_scope: `${VERSION[os]}を基準にした一般的な対処です。メーカー・機種・更新状況で表示や手順が異なる場合があります。`,
    ...(caution ? { caution } : {}),
    impact: impact || `${title}の原因を切り分け、改善する可能性があります。`,
  };
}

